import java.io.*;
import java.util.*;

public class B {
    static int[] readArray(int size, InputReader in) {
        int[] a = new int[size];
        for (int i = 0; i < size; i++) {
            a[i] = in.nextInt();
        }
        return a;
    }

    static long[] readLongArray(int size, InputReader in) {
        long[] a = new long[size];
        for (int i = 0; i < size; i++) {
            a[i] = in.nextLong();
        }
        return a;
    }

    final static long MOD = 998244353;

    private static long fastPow(long base, long exp) {
        long result = 1;
        long b = base % MOD;
        long e = exp;
        while (e > 0) {
            if ((e & 1) == 1) {
                result = (result * b) % MOD;
            }
            b = (b * b) % MOD;
            e >>= 1;
        }
        return result;
    }

    private static long inverseTwo() {
        return fastPow(2, MOD - 2);
    }

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        PrintWriter out = new PrintWriter(System.out);
        String[] parts = br.readLine().split(" ");
        long n = Long.parseLong(parts[0]);
        long m = Long.parseLong(parts[1]);
        long l = Long.parseLong(parts[2]);
        long r = Long.parseLong(parts[3]);
        long total = r - l + 1;
        if (n % 2 != 0 && m % 2 != 0) {
            out.println(fastPow(total, n * m));
        } else {
            long res1 = fastPow(total, n * m - 1);
            long res;
            if (total % 2 == 0) {
                res = res1 * (total / 2) % MOD;
            } else {
                res = (res1 * ((total + 1) / 2) % MOD + MOD - (res1 + MOD - 1) % MOD * inverseTwo() % MOD) % MOD;
            }
            out.println(res);
        }
        out.flush();
    }
}
